//! REA batch 11 lane b11-2-text (node:Text): event cases against pinned X_ITE 16.5.0 (oracle/rea-batch11-baseline/<name>, made by
//! `oracle/tools/rea_b11_text.py record`; worlds in oracle/synthetic-rea-b11-text, generated by oracle/tools/gen_rea_b11_text.py).
//! A Script records the output events of a Text (origin, textBounds, lineBounds) and of its input fields frame by frame into a field of
//! its own, so the scene text (`toVRMLString`) at every dumped frame carries it; the console is compared too. Compared like
//! rea_batch10_sai.rs: scene text exact, the sorted log exact, poses 1e-4. No rendering. The baseline is three identical X_ITE
//! recordings. The callbacks start at frame 10, after the oracle's warm-up: the frame the default font arrives in during the warm-up
//! is Chrome's I/O (oracle/synthetic-rea-b11-text/warm-stamp.wrl, documented open, not compared here).
//!
//! `REA_ONLY=<substring>` restricts the cases.

use serde_json::Value;
use std::path::{Path, PathBuf};
use std::process::Command;

fn quat(r: &[f64]) -> [f64; 4] {
    let n = (r[0] * r[0] + r[1] * r[1] + r[2] * r[2]).sqrt();
    let n = if n == 0.0 { 1.0 } else { n };
    let s = (r[3] / 2.0).sin() / n;
    [r[0] * s, r[1] * s, r[2] * s, (r[3] / 2.0).cos()]
}

fn nums(v: &Value) -> Vec<f64> {
    v.as_array()
        .map(|a| a.iter().filter_map(Value::as_f64).collect())
        .unwrap_or_default()
}

fn compare_case(root: &Path, name: &str, world: &str, script: &str, failures: &mut Vec<String>) {
    let dir = root.join(format!("oracle/rea-batch11-baseline/{name}"));
    let js: Value =
        serde_json::from_str(&std::fs::read_to_string(dir.join("js.json")).unwrap()).unwrap();
    let out = std::env::temp_dir().join(format!("rea-batch11-text-{}-{name}", std::process::id()));
    std::fs::create_dir_all(&out).unwrap();
    let rs_json = out.join("rs.json");
    let status = Command::new(env!("CARGO_BIN_EXE_x3d-drive"))
        .current_dir(root)
        .args([world, script, "--oracle", "oracle"])
        .arg("--out")
        .arg(&rs_json)
        .arg("--warmup-from")
        .arg(dir.join("js.json"))
        .status()
        .unwrap();
    let mut fail = |what: String| failures.push(format!("{name}: {what}"));

    if !status.success() {
        return fail(format!("x3d-drive exited with {status}"));
    }

    let rs: Value = serde_json::from_str(&std::fs::read_to_string(&rs_json).unwrap()).unwrap();

    if js["ok"] != Value::Bool(true) || rs["ok"] != Value::Bool(true) {
        return fail(format!("ok js {} rs {}", js["ok"], rs["ok"]));
    }

    let mut bad = vec![];

    for (k, a) in js["vrml"].as_object().unwrap() {
        if rs["vrml"].get(k) != Some(a) {
            bad.push(k.clone());
        }
    }

    if !bad.is_empty() {
        bad.sort_by_key(|k| k.parse::<u32>().unwrap_or(0));
        fail(format!(
            "scene text differs at {} dumped frames, first {}",
            bad.len(),
            bad[0]
        ));
    }

    // `"console": true` in the script: every console message, in order.
    if js.get("console") != rs.get("console") {
        fail(format!(
            "console differs: {} / {}",
            js["console"], rs["console"]
        ));
    }

    if js.get("log") != rs.get("log") {
        fail(format!("log differs: {} / {}", js["log"], rs["log"]));
    }

    for (k, a) in js["poses"].as_object().unwrap() {
        let Some(b) = rs["poses"].get(k) else {
            fail(format!("pose at frame {k} missing"));
            continue;
        };
        let d = |key: &str| {
            nums(&a[key])
                .iter()
                .zip(nums(&b[key]))
                .map(|(p, q)| (p - q).abs())
                .fold(0.0, f64::max)
        };
        let (qa, qb) = (
            quat(&nums(&a["orientation"])),
            quat(&nums(&b["orientation"])),
        );
        let angle = 2.0
            * qa.iter()
                .zip(qb)
                .map(|(p, q)| p * q)
                .sum::<f64>()
                .abs()
                .min(1.0)
                .acos();
        let viewpoint = a["viewpoint"] == b["viewpoint"] || b["viewpoint"] == "<default>";

        if d("position") > 1e-4
            || d("centerOfRotation") > 1e-4
            || angle > 1e-4
            || a["viewer"] != b["viewer"]
            || !viewpoint
        {
            fail(format!("pose frame {k} differs"));
        }
    }

    let _ = std::fs::remove_dir_all(&out);
}

#[test]
fn rea_batch11_text_cases_match_x_ite() {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .canonicalize()
        .unwrap();
    let cases =
        std::fs::read_to_string(root.join("oracle/rea-batch11-baseline/text-cases.txt")).unwrap();
    let only = std::env::var("REA_ONLY").ok();
    let mut failures = vec![];
    let mut checked = 0;

    for line in cases.lines().filter(|l| !l.trim().is_empty()) {
        let f: Vec<&str> = line.split_whitespace().collect();

        if only.as_deref().is_some_and(|o| !f[0].contains(o)) {
            continue;
        }

        compare_case(&root, f[0], f[1], f[2], &mut failures);
        checked += 1;
    }

    eprintln!("{checked} cases checked");
    assert!(
        failures.is_empty(),
        "{} failures:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
